import {escapeHTML as esc} from './discovery.js';
export async function showVerification(main){
 const host=document.createElement('section');host.className='panel verification';host.innerHTML='<h2>Archive verification</h2><p>Loading saved verification report…</p>';(main.matches('.guide')?main:main.querySelector('.guide')).append(host);
 try{const r=await fetch('./data/verification-summary.json');if(!r.ok)throw Error();const data=await r.json();if(!host.isConnected)return;const c=data.sessions['2026'];host.innerHTML=`<h2>Archive verification</h2><p><strong>2026: ${c.retrieved.toLocaleString()} of ${c.expected.toLocaleString()} indexed measures.</strong> ${c.metadataComplete?'All indexed and listed measure identifiers are accounted for.':'Metadata coverage is incomplete or inconsistent; see the verification report.'}</p><p>${c.versionRecords.toLocaleString()} version records · ${c.actionRecords.toLocaleString()} actions · ${c.documentReferences.toLocaleString()} document references.</p><p>Voting detail: ${data.verifiedVoteDetails.toLocaleString()} of ${data.voteReferences.toLocaleString()} referenced decisions verified; ${data.missingVoteDetails.length.toLocaleString()} missing or unparsed. Individual entries: ${data.individualEntries.toLocaleString()}. This does not establish that every vote that occurred has an official record.</p><p>Index retrieved ${esc(data.sources.index2026.retrievedAt)}. Archive check completed ${esc(data.voteAcquisitionCheckedAt)}. Individual source retrieval dates are preserved with each record; check times are not publication dates.</p><p>Document references preserve official version and file identifiers; linked documents are not a complete offline text archive. Statutory references do not independently establish current law. The four reviewed explanations remain separate.</p><details><summary>Verification sources and limitations</summary><p><a href="${esc(data.sources.index2026.url)}">Official index (machine-readable JSON)</a> · <a href="${esc(data.sources.listing2026.url)}">Official session listing</a> · <a href="./data/verification-report.json" target="_blank" rel="noopener">Full verification report (machine-readable JSON)</a></p><p>Missing index records: ${c.missingIndexRecords.length}. Missing listing records: ${c.missingListingRecords.length}. Source-status differences: ${data.officialStatusDifferences.length}. Source-title differences: ${data.officialTitleDifferences.length}. Conflicting listing rows: ${data.officialListingConflicts.length}. Individual entries without a verified profile association: ${data.unresolvedIndividualEntries.toLocaleString()}. Names remain visible without guessed links.</p></details>`;
 }catch{if(host.isConnected)host.innerHTML='<h2>Archive verification</h2><p>Saved verification report unavailable. No claim of complete coverage can be made from this page.</p>'}
}
